#accountName {
  font-size: 1.2em;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  margin-block: 0;
  /* Prevents UI jumping when dynamically changing the content. */
  @media (-moz-platform: linux), (-moz-platform: windows) {
    min-block-size: 21px;
  }

  @media (-moz-platform: macos) {
    min-block-size: 17px;
  }
}
